using System;
using System.Collections.Generic;

public class HashAggregationOperator
{
    private readonly Dictionary<int, AggregationGroup> _aggregationGroups = new Dictionary<int, AggregationGroup>();
    private readonly int _maxMemorySize;
    private readonly DiskSpillManager _diskSpillManager;

    public HashAggregationOperator(int maxMemorySize, DiskSpillManager diskSpillManager)
    {
        _maxMemorySize = maxMemorySize;
        _diskSpillManager = diskSpillManager;
    }

    // Process data and perform hash aggregation
    public void ProcessData(byte[] data)
    {
        // Parse the data and extract the key and value
        var key = GetKey(data);
        var value = GetValue(data);

        // Check if the aggregation group exists
        if (_aggregationGroups.TryGetValue(key, out var group))
        {
            // Update the existing group
            group.Update(value);
        }
        else
        {
            // Create a new group if it doesn't exist
            group = new AggregationGroup(key);
            group.Update(value);
            _aggregationGroups.Add(key, group);

            // Check if memory limits are exceeded
            if (GetMemorySize() > _maxMemorySize)
            {
                // Spill the aggregation groups to disk
                _diskSpillManager.Spill(_aggregationGroups);
                _aggregationGroups.Clear();
            }
