## Disk Spill Manager

This component will handle spilling the intermediate hash tables to disk when memory limits are exceeded.

```csharp
using System;
using System.Collections.Generic;
using System.IO;

public class DiskSpillManager
{
    private readonly string _spillDirectory;

    public DiskSpillManager(string spillDirectory)
    {
        _spillDirectory = spillDirectory;
    }

    // Spill the aggregation groups to disk
    public void Spill(Dictionary<int, AggregationGroup> aggregationGroups)
    {
        foreach (var group in aggregationGroups.Values)
        {
            using (var fileStream = new FileStream(Path.Combine(_spillDirectory, group.GetSum().ToString()), FileMode.Create))
            {
                using (var binaryWriter = new BinaryWriter(fileStream))
                {
                    // Serialize the group to disk
                    binaryWriter.Write(group.GetSum());
                }
            }
        }
    }

    // Load the spilled data from disk
    public Dictionary<int, AggregationGroup> LoadSpilledData()
    {
        var aggregationGroups = new Dictionary<int, AggregationGroup>();

        foreach (var file in Directory.GetFiles(_spillDirectory))
        {
            using (var fileStream = new FileStream(file, FileMode.Open))
            {
                using (var binaryReader = new BinaryReader(fileStream))
                {
                    // Deserialize the group from disk
                    var sum = binaryReader.ReadInt32();
                    var group = new AggregationGroup(sum);
                    aggregationGroups.Add(sum, group);
                }
            }
        }

        return aggregationGroups;
    }
}
```

## Usage Example

```csharp
public class Program
{
    public static void Main()
    {
        var networkExchangeOperator = new NetworkExchangeOperator(1024, 1024);
        var diskSpillManager = new DiskSpillManager("spill_directory");
        var hashAggregationOperator = new HashAggregationOperator(1024, diskSpillManager);

        // Enqueue data to be processed
        networkExchangeOperator.EnqueueOutput(new byte[] { 1, 2, 3 });
        networkExchangeOperator.EnqueueOutput(new byte[] { 4, 5, 6 });

        // Process the data
        for (int i = 0; i < 2; i++)
        {
            var data = networkExchangeOperator.DequeueInput();
            hashAggregationOperator.ProcessData(data);
        }

        // Load the spilled data from disk
        var spilledData = diskSpillManager.LoadSpilledData();

        // Print the results
        foreach (var group in spilledData.Values)
        {
            Console.WriteLine($"Sum: {group.GetSum()}");
        }
    }
}
